@startuml

class Well {
  + code : string
  + getPollutionRate() : float
}

abstract class OnshoreWell {
  + surfaceExtension : float
}

abstract class OffshoreWell {
  + installationYear : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

OnshoreWell --|> Well
OffshoreWell --|> Well

Well "1" -- "*" Extraction
OilCompany "1" -- "*" Extraction
Extraction "*" -- "1" Well
Extraction "*" -- "1" OilCompany

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

